  "customers": [],
  "origin": "William Falcon began building PyTorch Lightning as an undergraduate at Columbia in 2015 and open-sourced it during his PhD at NYU and Facebook AI Research. He founded the company as Grid.ai in 2019 with Luis Capelo, and it later became Lightning AI. In June 2022 it raised a $40M Series B led by Coatue, bringing total funding to $58.6M. In August 2025 Lightning added a multicloud GPU marketplace with AWS, Google Cloud, Lambda, Nebius, Nscale and Voltage Park.",
  "today": "Lightning AI completed its merger with Voltage Park in January 2026. The combined company operates under the Lightning AI name, with Falcon as CEO and former Voltage Park CEO Ozan Kaya as president. Voltage Park was built with about $900M from the Navigation Fund, a nonprofit started by Ripple co-founder Jed McCaleb. The deal valued Lightning AI at more than $2.5B, and the company says ARR grew from $18M in 2024 to more than $500M. By September 2026 it ran more than 40,000 NVIDIA GPUs, including H100, B200 and GB300 systems, across nine US data centers.",
  "platform": "Lightning's software covers large-scale data preparation, multi-node training, model serving, large-scale inference, team management and observability, all accessed from GPUs in one place. Teams can orchestrate with Kubernetes, Slurm, bare metal or Lightning's own tools. Customers can keep running Lightning on AWS or other clouds and burst into Lightning's own GPUs. The company also supports hybrid, on-premises and air-gapped deployments.",
  "outlook": "The merger makes Lightning AI responsible for financing and filling a fleet of more than 40,000 GPUs as well as selling software. In September 2026 it hired Heather Paduck, who has data center financing experience, as CFO to lead capital strategy for more GPU and data center investment. Sam Yagan serves as executive chairman.",
